UPDATE film f
SET f.score = (SELECT ROUND(AVG(m.score), 1) FROM mark m WHERE m.film_id = f.id)
WHERE f.id = #{filmId}

UPDATE film
title = #{title}, content = #{content}, time = #{time}, english = #{english}, start = #{start}, language = #{language}, resolution = #{resolution}, img = #{img}, employee = #{employee}, area_id = #{areaId}, status = #{status}, box_office = #{boxOffice}, video = #{video}, actor_id = #{actorId},
WHERE id = #{id}
